import { spawn } from "node:child_process";
import { cp, mkdtemp, readdir, realpath, rm } from "node:fs/promises";
import { join } from "node:path";
export async function publishWiki(options) {
    const contentDir = await realpath(options.contentDir);
    const worktree = await mkdtemp(join(options.temporaryDirectory, "openwiki-wiki-"));
    const cloneDir = join(worktree, "repository");
    const auth = createGitAuthEnvironment(options.wikiGitUrl, options.token);
    try {
        await runGit(["clone", "--quiet", options.wikiGitUrl, cloneDir], worktree, auth);
        const branch = await runGit(["branch", "--show-current"], cloneDir, auth);
        if (!branch.stdout) {
            throw new Error("The GitHub Wiki has no default branch. Create its first page in the GitHub UI, then rerun publication.");
        }
        for (const entry of await readdir(cloneDir)) {
            if (entry !== ".git")
                await rm(join(cloneDir, entry), { recursive: true, force: true });
        }
        await cp(contentDir, cloneDir, { recursive: true });
        await runGit(["add", "-A"], cloneDir, auth);
        await options.beforePush?.(cloneDir);
        const diff = await runGit(["diff", "--cached", "--quiet"], cloneDir, auth, [0, 1]);
        if (diff.code === 0) {
            await pushSafely(cloneDir, branch.stdout, auth);
            return { changed: false, commitSha: "" };
        }
        await runGit(["config", "user.name", options.committerName], cloneDir, auth);
        await runGit(["config", "user.email", options.committerEmail], cloneDir, auth);
        await runGit(["commit", "--quiet", "-m", options.commitMessage], cloneDir, auth);
        const commit = await runGit(["rev-parse", "HEAD"], cloneDir, auth);
        await pushSafely(cloneDir, branch.stdout, auth);
        return { changed: true, commitSha: commit.stdout };
    }
    finally {
        await rm(worktree, { recursive: true, force: true });
    }
}
async function pushSafely(cloneDir, branch, auth) {
    try {
        await runGit(["push", "--quiet", "origin", `HEAD:${branch}`], cloneDir, auth);
    }
    catch (error) {
        throw new Error(`Unable to publish the GitHub Wiki without rewriting history. Rerun after resolving concurrent Wiki changes. ${errorMessage(error)}`);
    }
}
async function runGit(args, cwd, auth, acceptedExitCodes = [0]) {
    const result = await new Promise((resolvePromise, reject) => {
        const child = spawn("git", args, {
            cwd,
            env: { ...process.env, ...auth, GIT_TERMINAL_PROMPT: "0" },
            stdio: ["ignore", "pipe", "pipe"],
        });
        let stdout = "";
        let stderr = "";
        child.stdout.setEncoding("utf8").on("data", (chunk) => {
            stdout += chunk;
        });
        child.stderr.setEncoding("utf8").on("data", (chunk) => {
            stderr += chunk;
        });
        child.once("error", reject);
        child.once("close", (code) => resolvePromise({
            code: code ?? 1,
            stdout: stdout.trim(),
            stderr: stderr.trim(),
        }));
    });
    if (!acceptedExitCodes.includes(result.code)) {
        throw new Error(`git ${args[0] ?? "command"} failed: ${result.stderr || result.stdout}`);
    }
    return result;
}
export function createGitAuthEnvironment(wikiGitUrl, token) {
    if (!wikiGitUrl.startsWith("https://"))
        return {};
    const credential = Buffer.from(`x-access-token:${token}`, "utf8").toString("base64");
    return {
        GIT_CONFIG_COUNT: "1",
        GIT_CONFIG_KEY_0: "http.extraheader",
        GIT_CONFIG_VALUE_0: `AUTHORIZATION: basic ${credential}`,
    };
}
function errorMessage(error) {
    return error instanceof Error ? error.message : String(error);
}
